from collections import deque

def get_7_neighbors(grid, r, c):
    """Get 4-neighbors that are 7"""
    n, m = len(grid), len(grid[0])
    neighbors = []
    if r > 0 and grid[r-1][c] == 7:
        neighbors.append((r-1, c))
    if r < n - 1 and grid[r+1][c] == 7:
        neighbors.append((r+1, c))
    if c > 0 and grid[r][c-1] == 7:
        neighbors.append((r, c-1))
    if c < m - 1 and grid[r][c+1] == 7:
        neighbors.append((r, c+1))
    return neighbors

# Let me find connected components of 7s
def find_connected_components(grid):
    n, m = len(grid), len(grid[0])
    visited = set()
    components = []
    for r in range(n):
        for c in range(m):
            if grid[r][c] == 7 and (r, c) not in visited:
                component = []
                queue = deque([(r, c)])
                visited.add((r, c))
                while queue:
                    curr_r, curr_c = queue.popleft()
                    component.append((curr_r, curr_c))
                    for nr, nc in get_7_neighbors(grid, curr_r, curr_c):
                        if (nr, nc) not in visited:
                            visited.add((nr, nc))
                            queue.append((nr, nc))
                components.append(component)
    return components

